-- Synthetic disposable shape. Money owners below are exact repository bodies;
-- fixture admissions are direct SQL, never financial-owner replacements.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA extensions;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role' $$;
CREATE TABLE profiles(id uuid PRIMARY KEY,role text,diamonds bigint DEFAULT 100,diamond_balance bigint DEFAULT 100,diamond_multiplier numeric DEFAULT 1,username text,full_name text,updated_at timestamptz);
CREATE TABLE ca_operator_policy(id boolean PRIMARY KEY,enforce_named_roles boolean);
CREATE TABLE ca_operator_roles(key text PRIMARY KEY,is_legacy boolean);
CREATE TABLE ca_operator_role_permissions(role_key text,permission text);
CREATE TABLE ca_operator_grants(user_id uuid,role_key text,revoked_at timestamptz);
CREATE TABLE clubs(id uuid PRIMARY KEY,asset text);
CREATE TABLE tables(id uuid PRIMARY KEY,club_id uuid,tournament_id uuid,status text,current_players int,game_variant text,small_blind numeric,big_blind numeric);
CREATE TABLE tournaments(id uuid PRIMARY KEY);
CREATE TABLE table_seats(id uuid PRIMARY KEY,user_id uuid,table_id uuid,club_id uuid,stack numeric,joined_at timestamptz DEFAULT now(),left_at timestamptz,seat_number int,occupancy_id uuid UNIQUE,leave_pending boolean DEFAULT false,is_sitting_out boolean DEFAULT false,status text DEFAULT 'active');
CREATE TABLE hand_state_snapshots(table_id uuid,is_complete boolean);
CREATE TABLE club_members(user_id uuid,club_id uuid,chip_balance numeric,status text,joined_at timestamptz DEFAULT now(),updated_at timestamptz,PRIMARY KEY(user_id,club_id));
CREATE TABLE wallet_credit_idempotency(key text PRIMARY KEY,user_id uuid,amount numeric);
CREATE TABLE wallets(user_id uuid,wallet_type text,balance numeric,locked_balance numeric,updated_at timestamptz,PRIMARY KEY(user_id,wallet_type));
CREATE TABLE wallet_transactions(id uuid DEFAULT gen_random_uuid(),user_id uuid,wallet_type text,type text,amount numeric,category text,description text,table_id uuid,balance_after numeric);
CREATE TABLE chip_transactions(id uuid DEFAULT gen_random_uuid(),club_id uuid,to_user_id uuid,amount numeric,transaction_type text,notes text,table_id uuid,metadata jsonb);
CREATE TABLE cash_player_session(id uuid DEFAULT gen_random_uuid(),player_id uuid,scope_type text,scope_id uuid,closed_at timestamptz,closed_reason text,rejoin_window_ms int,baseline numeric);
CREATE TABLE cash_rejoin_constraints(id uuid DEFAULT gen_random_uuid(),player_id uuid,club_id uuid,variant text,sb numeric,bb numeric,required_stack numeric,left_at timestamptz,expires_at timestamptz,source_table_id uuid,barred_until timestamptz);
CREATE TABLE seat_cashout_receipts(occupancy_id uuid PRIMARY KEY,user_id uuid,table_id uuid,seat_id uuid,seat_number int,receipt jsonb);
CREATE TABLE seat_departure_requests(occupancy_id uuid PRIMARY KEY,user_id uuid,table_id uuid,seat_number int,leave_mode text);
CREATE TABLE seat_admin_departure_authorizations(occupancy_id uuid PRIMARY KEY,user_id uuid,table_id uuid,seat_number int,actor_id uuid,club_id uuid,reason text,created_at timestamptz DEFAULT now());
CREATE TABLE anti_cheat_events(event_type text,player_id uuid,club_id uuid,table_id uuid,details jsonb,triggered_by text);
CREATE TABLE poker_diamond_custody(id uuid PRIMARY KEY,user_id uuid,target_id uuid,purpose text,seat_id uuid,seat_joined_at timestamptz,occupancy_id uuid,balance bigint,state text,released_at timestamptz);
CREATE TABLE poker_diamond_movements(request_id uuid PRIMARY KEY,custody_id uuid,user_id uuid,action text,amount bigint,source_account text,destination_account text,wallet_journal_id uuid,request jsonb,receipt jsonb);
CREATE TABLE diamond_purchase_lots(id uuid PRIMARY KEY,created_at timestamptz DEFAULT now(),arena_reserved bigint);
CREATE TABLE poker_diamond_lot_reservations(lot_id uuid,custody_id uuid,amount bigint,consumed bigint,released_at timestamptz);
CREATE TABLE diamond_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,amount bigint,transaction_type text,type text,description text,balance_after bigint,reference_id text,metadata jsonb,counterparty text,issuance_class text,source text,created_at timestamptz DEFAULT now(),UNIQUE(user_id,reference_id));
CREATE TABLE diamond_debts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,purchase_id uuid,amount bigint,reason text,created_at timestamptz DEFAULT now(),settled_at timestamptz,settled_by text);
CREATE TABLE ca_mint_ledger(op_id text PRIMARY KEY,action text,asset text,holder_type text,holder_id uuid,holder_label text,amount numeric,balance_before numeric,balance_after numeric,supply_after numeric,reason text,performed_by uuid,performed_by_label text,chip_ledger_id uuid,diamond_tx_id uuid,created_at timestamptz);
CREATE TABLE ca_diamond_rule_modes(rule text PRIMARY KEY,mode text);
CREATE TABLE ca_payout_freeze(scope text,cleared_at timestamptz);
CREATE FUNCTION floor_assert(boolean,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF $1 IS DISTINCT FROM true THEN RAISE EXCEPTION 'floor qualification assertion: %',$2; END IF; END $$;
