CREATE TABLE admin_audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_user_id uuid,action text,target_type text,target_id text,details jsonb,before_state jsonb,after_state jsonb,ip_address text,user_agent text,actor_role text,request_id text,created_at timestamptz DEFAULT now());
